const defaults=()=>({version:1,title:'',legendTitle:'图例',county:'',level:'towns',labels:true,borderColor:'#80978d',borderWidth:0.6,countyBorderColor:'#385d4b',countyBorderWidth:1.5,selected:'blue',palette:presetPalette(),settingsRevision:2,fills:{towns:{},counties:{},council:{},legislative:{}},fillMode:'solid',gradient:{groupBy:'candidate',metric:'share',min:0,max:null},legend:{show:true,onlyUsed:true,fontSize:12,caption:'',hidden:[]},elections:{towns:{},counties:{},council:{},legislative:{}}});
