try{const s=localStorage.getItem(KEY);if(s)state=cleanProject(JSON.parse(s))}catch(e){console.warn('本地方案未载入',e.message)}
function persist(){clearTimeout(persistTimer);persistTimer=setTimeout(()=>{try{localStorage.setItem(KEY,JSON.stringify(state));$('saved').textContent='● 已自动保存'}catch(e){$('saved').textContent='未能自动保存，请保存方案';}},140)}
