 if(state.level==='counties'&&!state.county&&insetLabels[f.name]){const q=insetLabels[f.name];result.push({f,x:q[0]*t.scale+t.tx,y:q[1]*t.scale+t.ty,ax,ay,out:false,font,inset:true});continue;}
