 const min=Number(s.gradient?.min);if(Number.isFinite(min)&&min>=0)out.gradient.min=min;
 if(s.gradient?.max!==null&&s.gradient?.max!==undefined&&s.gradient?.max!==''){const max=Number(s.gradient.max);if(Number.isFinite(max)&&max>out.gradient.min&&(out.gradient.metric==='votes'||max<=100))out.gradient.max=max;else out.gradient.min=0;}
