function syncElectionControls(){
 $('solidMode').classList.toggle('active',state.fillMode==='solid');$('gradientMode').classList.toggle('active',state.fillMode==='gradient');$('solidMode').setAttribute('aria-pressed',state.fillMode==='solid');$('gradientMode').setAttribute('aria-pressed',state.fillMode==='gradient');$('gradientControls').hidden=state.fillMode!=='gradient';
 $('gradientGroup').value=state.gradient.groupBy;$('gradientMetric').value=state.gradient.metric;$('gradientMin').value=state.gradient.min;$('gradientMax').value=state.gradient.max===null?'':state.gradient.max;$('gradientUnit').textContent=state.gradient.metric==='share'?'%':'票';
 $('mapVersionNote').textContent=state.level==='council'?'2026 年区域议员选区 · 161 区':state.level==='legislative'?'2024 年区域立委选区 · 73 区':'';
 $('electionScopeNote').hidden=!['council','legislative'].includes(state.level);
 if(!data)return;const select=$('dataRegion'),previous=select.value;select.replaceChildren();for(const f of currentItems()){const o=document.createElement('option');o.value=f.id;o.textContent=f.county+(f.name===f.county?'':' · '+f.name);select.append(o)}if(currentItems().some(f=>f.id===previous))select.value=previous;
 const usable=currentItems().filter(f=>regionResult(f).status==='winner').length;$('dataCoverage').textContent=state.fillMode==='gradient'?`当前视图 ${usable} / ${currentItems().length} 个区域有可用渐变数据`:'';
}
let editRegionId='',editRegionLevel='',voteDraft=[];
function draftRecord(){return{totalVotes:$('validVoteTotal').value,rows:voteDraft.map(r=>({name:r.name,partyId:r.partyId,votes:r.votes,share:r.share}))}}
function previewVoteDraft(){try{const valid=ElectionCore.validate(draftRecord()),result=ElectionCore.summarize(draftRecord(),state.gradient.groupBy,state.gradient.metric);$('voteError').textContent=result.status==='invalid'?result.message:'';$('votePreview').textContent=result.status==='winner'?'已录入最高票：'+(state.gradient.groupBy==='party'?paletteById(result.leader.partyId)?.name:result.leader.name)+' · '+metricText(result.value):result.message;if(valid.derivedTotal)$('votePreview').textContent+='；得票率按已录入得票合计计算';}catch(e){$('voteError').textContent=e.message;$('votePreview').textContent=''}}
function renderVoteRows(){const body=$('voteRows');body.replaceChildren();voteDraft.forEach((r,i)=>{const tr=document.createElement('tr');for(const key of ['name','partyId','votes','share']){const td=document.createElement('td'),input=key==='partyId'?document.createElement('select'):document.createElement('input');if(key==='partyId'){for(const p of state.palette){const o=document.createElement('option');o.value=p.id;o.textContent=p.name;input.append(o)}}else{input.type='text';if(key==='name')input.maxLength=80;if(['votes','share'].includes(key)){input.inputMode='decimal';input.placeholder=key==='votes'?'票数':'0—100';}}input.value=r[key]??'';input.setAttribute('aria-label',`第${i+1}条${{name:'候选人',partyId:'政党',votes:'得票数',share:'得票率'}[key]}`);input.oninput=()=>{r[key]=input.value;previewVoteDraft()};td.append(input);tr.append(td)}const td=document.createElement('td'),remove=document.createElement('button');remove.type='button';remove.textContent='删除';remove.setAttribute('aria-label',`删除第${i+1}条数据`);remove.onclick=()=>{voteDraft.splice(i,1);renderVoteRows();previewVoteDraft()};td.append(remove);tr.append(td);body.append(tr)});}
function openVoteEditor(f){
 editRegionId=f.id;editRegionLevel=state.level;$('dataRegion').value=f.id;const record=state.elections[state.level][f.id];voteDraft=clone(record?.rows||[{name:'',partyId:state.selected,votes:'',share:''}]);$('validVoteTotal').value=record?.totalVotes??'';$('voteDialogTitle').textContent=f.county+(f.name===f.county?'':' · '+f.name);$('voteError').textContent='';renderVoteRows();previewVoteDraft();$('voteDialog').showModal();
}
function afterElectionEdit(){recolor();renderPalette();renderLegend();renderList();updateProgress();updateBrush();persist()}
$('editVoteData').onclick=()=>{const f=currentItems().find(f=>f.id===$('dataRegion').value)||currentItems()[0];if(f)openVoteEditor(f)};
$('addVoteRow').onclick=()=>{voteDraft.push({name:'',partyId:state.selected,votes:'',share:''});renderVoteRows();previewVoteDraft()};
$('validVoteTotal').oninput=previewVoteDraft;$('cancelVoteEdit').onclick=()=>$('voteDialog').close();
$('saveVoteEdit').onclick=()=>{try{const valid=ElectionCore.validate(draftRecord()),record={totalVotes:valid.totalVotes,rows:valid.rows},r=ElectionCore.summarize(record,state.gradient.groupBy,state.gradient.metric);if(r.status==='invalid')throw Error(r.message);pushHistory();if(valid.rows.length)state.elections[editRegionLevel][editRegionId]=record;else delete state.elections[editRegionLevel][editRegionId];$('voteDialog').close();afterElectionEdit();toast('区域数据已保存')}catch(e){$('voteError').textContent=e.message}};
$('clearVoteEdit').onclick=()=>{voteDraft=[];$('validVoteTotal').value='';renderVoteRows();previewVoteDraft()};
for(const [id,mode]of [['solidMode','solid'],['gradientMode','gradient']])$(id).onclick=()=>{if(state.fillMode===mode)return;pushHistory();state.fillMode=mode;syncElectionControls();render();persist()};
for(const [id,key]of [['gradientGroup','groupBy'],['gradientMetric','metric']])$(id).onchange=()=>{pushHistory();state.gradient[key]=$(id).value;if(key==='metric'){state.gradient.min=0;state.gradient.max=null;}syncElectionControls();render();persist()};
$('applyGradientRange').onclick=()=>{try{const min=ElectionCore.number($('gradientMin').value,state.gradient.metric==='share')??0;let max=$('gradientMax').value.trim()===''?null:Number($('gradientMax').value);if(!Number.isFinite(min)||min<0||(max!==null&&(!Number.isFinite(max)||max<=min))||(state.gradient.metric==='share'&&(min>=100||max>100)))throw Error('请填写有效范围：上限大于下限，得票率在 0%—100% 之间');pushHistory();state.gradient.min=min;state.gradient.max=max;$('gradientRangeError').textContent='';render();persist()}catch(e){$('gradientRangeError').textContent=e.message}};
function csvCell(v){v=String(v??'');if(/^[=+@\t\r-]/.test(v))v="'"+v;return'"'+v.replace(/"/g,'""')+'"'}
function exportVoteCSV(template=false){const rows=[['选区代码','县市','选区','候选人','政党','得票数','得票率(%)','有效票总数']];for(const f of currentItems()){const r=state.elections[state.level][f.id];if(template||!r?.rows.length){rows.push([f.id,f.county,f.name,'','','','',''])}else for(const row of r.rows)rows.push([f.id,f.county,f.name,row.name,paletteById(row.partyId)?.name||'',row.votes,row.share,r.totalVotes]);}download(new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),levelLabel(state.level)+(template?'数据模板':'投票数据')+'.csv')}
$('downloadVoteTemplate').onclick=()=>exportVoteCSV(true);$('exportVoteData').onclick=()=>exportVoteCSV(false);$('importVoteData').onclick=()=>$('voteCsvFile').click();
let pendingVoteImport=null;
function normalizePlace(s){return simplify(String(s||'')).replace(/臺/g,'台').replace(/选举区/g,'选区').replace(/\s/g,'').replace(/第0+(\d)/g,'第$1')}
function prepareVoteImport(text){
 const raw=ElectionCore.csv(text);if(raw.length<2)throw Error('CSV 至少需要表头和一条数据');if(raw.length>50001)throw Error('一次最多导入 50000 条记录');
 const headers=raw[0].map(s=>normalizePlace(s).replace(/[()（）%]/g,'')),col=(...names)=>headers.findIndex(h=>names.includes(h)),cols={id:col('选区代码','区域代码','id','code'),county:col('县市','county'),region:col('选区','区域','乡镇市区','region'),name:col('候选人','候选人姓名','name'),party:col('政党','党派','party'),votes:col('得票数','票数','votes'),share:col('得票率','share'),total:col('有效票总数','有效票','total')};
 if(cols.id<0&&cols.region<0)throw Error('CSV 需要“选区代码”或“选区”列');if(cols.party<0)throw Error('CSV 需要“政党”列');if(cols.votes<0&&cols.share<0)throw Error('CSV 需要“得票数”或“得票率”列');
 const palette=clone(state.palette),records={},errors=[];let imported=0;
 for(let i=1;i<raw.length;i++){const row=raw[i],get=k=>cols[k]<0?'':(row[cols[k]]||'').trim();if(!get('votes')&&!get('share')&&!get('name')&&!get('party'))continue;try{if(!get('votes')&&!get('share'))throw Error('请填写得票数或得票率');let matches=data[state.level].filter(f=>get('id')?f.id===get('id'):normalizePlace(f.name)===normalizePlace(get('region'))||normalizePlace(f.county+f.name)===normalizePlace(get('region')));if(get('county'))matches=matches.filter(f=>normalizePlace(f.county)===normalizePlace(get('county')));if(matches.length!==1)throw Error(matches.length?'同名区域需要填写县市或选区代码':'未找到对应区域，请下载当前图层的模板');const f=matches[0],party=simplify(get('party'));if(!party)throw Error('政党不能为空');if(party.length>40)throw Error('政党名称不能超过40个字符');const matchedPreset=partyMatch(party);let p=palette.find(p=>normalizePlace(p.name)===normalizePlace(party)||(matchedPreset&&(p.id===matchedPreset.id||partyMatch(p.name)?.id===matchedPreset.id)));if(!p){if(palette.length>=64)throw Error('政党/颜色类别超过64个');const preset=partyMatch(party);p={id:'import-'+palette.length+'-'+Date.now().toString(36),name:party,color:preset?.color||'#607d8b'};palette.push(p)}const record=records[f.id]||(records[f.id]={totalVotes:null,rows:[]}),total=ElectionCore.number(get('total'));if(total!==null){if(record.totalVotes!==null&&record.totalVotes!==total)throw Error('同一区域的有效票总数不一致');record.totalVotes=total;}record.rows.push({name:get('name'),partyId:p.id,votes:ElectionCore.number(get('votes')),share:ElectionCore.number(get('share'),true)});imported++;}catch(e){errors.push(`第 ${i+1} 行：${e.message}`)}}
 for(const [id,r]of Object.entries(records)){try{ElectionCore.validate(r);const result=ElectionCore.summarize(r,state.gradient.groupBy,state.gradient.metric);if(result.status==='invalid')throw Error(result.message)}catch(e){errors.push(`${data[state.level].find(f=>f.id===id)?.name}：${e.message}`)}}
 if(!imported&&!errors.length)throw Error('没有可导入的数值，请先填写模板');return{palette,records,errors,imported,level:state.level};
}
$('voteCsvFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('CSV 不能超过10MB');pendingVoteImport=prepareVoteImport(await file.text());const p=pendingVoteImport;$('importSummary').textContent=`${p.imported} 条记录，${Object.keys(p.records).length} 个区域。导入会替换这些区域的全部数据，其他区域保留。`;$('importErrors').textContent=p.errors.slice(0,20).join('\n');$('confirmVoteImport').disabled=!!p.errors.length;$('voteImportDialog').showModal();}catch(err){toast(err.message)}finally{e.target.value=''}};
$('cancelVoteImport').onclick=()=>{pendingVoteImport=null;$('voteImportDialog').close()};$('confirmVoteImport').onclick=()=>{const p=pendingVoteImport;if(!p||p.errors.length)return;pushHistory();state.palette=p.palette;Object.assign(state.elections[p.level],p.records);state.fillMode='gradient';$('voteImportDialog').close();pendingVoteImport=null;syncInputs();render();persist();toast('数据已导入，渐变地图已更新')};
let legendDraft=[];
function renderLegendEditor(){const list=$('legendEditRows');list.replaceChildren();legendDraft.forEach((p,i)=>{const row=document.createElement('div');row.className='legend-edit-row';const show=document.createElement('input');show.type='checkbox';show.checked=!p.hidden;show.setAttribute('aria-label','显示'+p.name+'图例');show.onchange=()=>p.hidden=!show.checked;const color=document.createElement('input');color.type='color';color.value=p.color;color.setAttribute('aria-label','图例颜色 '+p.name);color.oninput=()=>p.color=color.value;const name=document.createElement('input');name.value=p.name;name.maxLength=40;name.setAttribute('aria-label','图例名称 '+p.name);name.oninput=()=>p.name=name.value;row.append(show,color,name);for(const [direction,label]of [[-1,'上移'],[1,'下移']]){const b=document.createElement('button');b.type='button';b.textContent=direction<0?'↑':'↓';b.setAttribute('aria-label',label+p.name);b.disabled=i+direction<0||i+direction>=legendDraft.length;b.onclick=()=>{[legendDraft[i],legendDraft[i+direction]]=[legendDraft[i+direction],legendDraft[i]];renderLegendEditor()};row.append(b)}list.append(row)})}
$('editLegend').onclick=()=>{legendDraft=state.palette.map(p=>({...p,hidden:state.legend.hidden.includes(p.id)}));$('legendDisplay').checked=state.legend.show;$('legendOnlyUsed').checked=state.legend.onlyUsed;$('legendFont').value=state.legend.fontSize;$('legendCaption').value=state.legend.caption;$('legendDialogTitle').value=state.legendTitle;renderLegendEditor();$('legendDialog').showModal()};
$('cancelLegendEdit').onclick=()=>$('legendDialog').close();$('saveLegendEdit').onclick=()=>{if(legendDraft.some(p=>!p.name.trim()))return toast('图例名称不能为空');if(new Set(legendDraft.map(p=>normalizePlace(p.name))).size!==legendDraft.length)return toast('图例名称不能重复');pushHistory();state.palette=legendDraft.map(({hidden,...p})=>({...p,name:simplify(p.name.trim())}));state.legend={show:$('legendDisplay').checked,onlyUsed:$('legendOnlyUsed').checked,fontSize:Math.max(9,Math.min(22,Number($('legendFont').value)||12)),caption:simplify($('legendCaption').value).slice(0,80),hidden:legendDraft.filter(p=>p.hidden).map(p=>p.id)};state.legendTitle=simplify($('legendDialogTitle').value)||'图例';$('legendDialog').close();syncInputs();render();persist();toast('图例已更新，导出图片将使用相同图例')};
